  role: prop(item, ['權限設定', '權限', '权限设置', 'role', 'Role']) || prop(item, ['身份', '身分', 'identity', 'Identity']),
  identity: prop(item, ['身份', '身分', 'identity', 'Identity'])
}));
const user = users.find(u => u.account === account && u.password === password);
if (!user) {
  return [{ json: { ok: false, statusCode: 401, message: '帳號或密碼錯誤', checkedAccounts: users.map(u => u.account).filter(Boolean) } }];
}
return [{ json: { ok: true, id: user.id, name: user.name, account: user.account, role: user.role, identity: user.identity, permissions: user.role === '管理者' ? ['all'] : ['cases', 'events', 'legal'] } }];

